contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 targetSeed, bool freeze) public {
        address target = address(uint160(uint256(keccak256(abi.encodePacked(targetSeed, msg.sender)))));
        uint256 targetBalBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;

        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;

        uint256 targetBalAfter = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalAfter = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;

        assert(
            c.frozenAccount(target) == freeze
                && targetBalAfter == targetBalBefore
                && supplyAfter == supplyBefore
                && ownerBalAfter == ownerBalBefore
        );
    }

    receive() external payable {}
}

