pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 targetSeed, bool freeze) internal {
        address target = address(uint160(uint256(keccak256(abi.encodePacked(targetSeed, msg.sender)))));
        uint256 targetBalBefore;
        try c.balanceOf(target) returns (uint256 __r) { targetBalBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 ownerBalBefore;
        try c.balanceOf(msg.sender) returns (uint256 __r) { ownerBalBefore = __r; } catch { return; }
        try c.freezeAccount(target, freeze) {} catch { return; }
        uint256 targetBalAfter;
        try c.balanceOf(target) returns (uint256 __r) { targetBalAfter = __r; } catch { return; }
        uint256 supplyAfter;
        try c.totalSupply() returns (uint256 __r) { supplyAfter = __r; } catch { return; }
        uint256 ownerBalAfter;
        try c.balanceOf(msg.sender) returns (uint256 __r) { ownerBalAfter = __r; } catch { return; }
        assertTrue(c.frozenAccount(target) == freeze
                && targetBalAfter == targetBalBefore
                && supplyAfter == supplyBefore
                && ownerBalAfter == ownerBalBefore);
    }

    function testFuzz_run(uint256 targetSeed, bool freeze) public {
        _run(targetSeed, freeze);
    }

    receive() external payable {}
}
